package ca.humber.stockbridge.web;
import ca.humber.stockbridge.model.AppUser;import ca.humber.stockbridge.repo.AppUserRepository;import jakarta.validation.constraints.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller public class AccountController {private final AppUserRepository users;private final PasswordEncoder encoder;public AccountController(AppUserRepository u,PasswordEncoder e){users=u;encoder=e;}@GetMapping("/login")String login(){return "login";}@GetMapping("/register")String register(){return "register";}@PostMapping("/register")String create(@RequestParam String fullName,@RequestParam String email,@RequestParam String password,Model model){email=email.trim().toLowerCase(java.util.Locale.ROOT);if(fullName.trim().length()<2||fullName.length()>100||email.length()>254||!email.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")||password.length()<8||password.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72){model.addAttribute("error","Enter your name, a valid email and a password of at least 8 characters.");return "register";}if(users.findByEmailIgnoreCase(email).isPresent()){model.addAttribute("error","An account with this email already exists.");return "register";}AppUser user=new AppUser();user.fullName=fullName.trim();user.email=email.trim().toLowerCase();user.passwordHash=encoder.encode(password);user.role="STAFF";try{users.saveAndFlush(user);}catch(org.springframework.dao.DataIntegrityViolationException ex){model.addAttribute("error","An account with this email already exists.");return "register";}return "redirect:/login?registered";}}